from pathlib import Path
import re,json,urllib.parse,subprocess,hashlib
root=Path.cwd()
files=[root/'README.md',root/'AGENTS.md',*(root/'docs').rglob('*.md'),*(root/'assets').rglob('*.md')]
files=sorted(set(p for p in files if not ('diario-ia' in p.parts and p.name not in ['README.md','CONTEXTO-ATUAL.md'])))
def headings(p):
 counts={};slugs=set()
 for line in re.sub(r'```[\s\S]*?```','',p.read_text()).splitlines():
  m=re.match(r'^#{1,6}\s+(.+?)\s*#*$',line)
  if not m:continue
  slug=re.sub(r'[^\w\- ]','',m[1].lower()).replace(' ','-');n=counts.get(slug,0);counts[slug]=n+1;slugs.add(slug+(f'-{n}' if n else ''))
 return slugs
errors=[];links=0
for p in files:
 text=re.sub(r'```[\s\S]*?```','',p.read_text())
 for href in re.findall(r'!?\[[^\]]*\]\(([^\n]+?)\)',text):
  href=href.strip().split(' "')[0].strip('<>')
  if re.match(r'^(https?:|mailto:|data:)',href):continue
  path,sep,fragment=href.partition('#');target=urllib.parse.unquote(path.split('?')[0]);q=(p.parent/target).resolve() if target else p
  links+=1
  if not q.exists():errors.append(f'{p.relative_to(root)}: arquivo ausente {href}')
  elif fragment and q.suffix=='.md' and urllib.parse.unquote(fragment) not in headings(q):errors.append(f'{p.relative_to(root)}: âncora ausente {href}')
architecture=(root/'docs/ARQUITETURA.md').read_text();reference=(root/'docs/REFERENCIA-METODOS.md').read_text();commands=(root/'docs/COMANDOS.md').read_text()
modules=sorted((root/'src/js').rglob('*.js'));class_count=0
for p in modules:
 rel=p.relative_to(root).as_posix()
 if f'](../{rel})' not in architecture:errors.append('Módulo fora do catálogo: '+rel)
 if f'## {rel}\n' not in reference:errors.append('Módulo fora da referência: '+rel)
 exports=re.findall(r'^export\s+(?:async\s+)?(?:const|class|function|let)\s+(\w+)',p.read_text(),re.M)
 section=reference.split(f'## {rel}\n',1)[1].split('\n## ',1)[0]
 for name in exports:
  if '`'+name+'`' not in section:errors.append('Export sem referência: '+rel+' '+name)
 class_count+=len(re.findall(r'export\s+class\s+',p.read_text()))
package=json.loads((root/'package.json').read_text());qa={}
for p in sorted((root/'docs/diario-ia/pacotes').glob('*.json')):qa.update(json.loads(p.read_text()).get('qaCommands',{}))
for name in package['scripts']:
 text='`npm '+('test' if name=='test' else 'run '+name)+'`'
 if text not in commands:errors.append('Comando npm fora do catálogo: '+name)
for name in re.findall(r'npm run journal:qa -- ([\w:.-]+)',commands):
 if name.startswith('script:'):
  target='scripts/'+name.removeprefix('script:')
  if not any(any(e['path']==target for e in json.loads(p.read_text())['files']) for p in (root/'docs/diario-ia/pacotes').glob('*.json')):errors.append('Script documentado ausente do acervo: '+name)
 elif name not in qa:errors.append('Alias documentado ausente do acervo: '+name)
# A contextualização dos JSONs antigos preserva integralmente seus valores originais.
for p in (root/'docs/battle-mode').glob('*spec.json'):
 old=json.loads(subprocess.check_output(['git','show','HEAD:'+p.relative_to(root).as_posix()],cwd=root));old.pop('_documentacao',None);now=json.loads(p.read_text());now.pop('_documentacao',None)
 if now!=old:errors.append('Design original alterado: '+p.name)
# A fotografia documental dos parâmetros corresponde ao código importado.
js="""import {BATTLE_TUNING,BATTLE_ORDER,BATTLE_TRANSITION_DURATION} from './src/js/toy-room/BattleConfig.js';import {ARENA_TUNING} from './src/js/toy-room/ArenaPlayerController.js';import {ARENA_ENEMIES} from './src/js/toy-room/ArenaEnemies.js';import {ARENA_SWORD} from './src/js/toy-room/ArenaCombatRules.js';console.log(JSON.stringify({BATTLE_ORDER,BATTLE_TUNING,BATTLE_TRANSITION_DURATION,ARENA_TUNING,ARENA_ENEMIES,ARENA_SWORD}));"""
actual=json.loads(subprocess.check_output(['node','--input-type=module','-e',js],cwd=root));saved=json.loads((root/'docs/arena/configuracao-atual.json').read_text())['perfis']
if actual!=saved:errors.append('Parâmetros documentados divergem do código.')
for name in ['express','jpeg-js','pngjs']:
 lock=json.loads((root/'package-lock.json').read_text())['packages']['node_modules/'+name]['version']
 if f'/ {lock} |' not in (root/'docs/DEPENDENCIAS.md').read_text():errors.append('Versão de dependência divergente: '+name)
# Regeneração idempotente prova que a referência está atualizada.
before=(root/'docs/REFERENCIA-METODOS.md').read_bytes();subprocess.run(['node','scripts/generate-method-reference.js'],cwd=root,check=True,stdout=subprocess.DEVNULL)
if before!=(root/'docs/REFERENCIA-METODOS.md').read_bytes():errors.append('Referência gerada estava desatualizada.')
print(json.dumps({'documentosRevisados':len(files),'linksLocais':links,'modulosCatalogados':len(modules),'classes':class_count,'comandosNpm':len(package['scripts']),'erros':errors},ensure_ascii=False,indent=2))
raise SystemExit(bool(errors))
